#include<bits/stdc++.h>
using namespace std;using P=pair<int,int>;P rot(P p,int h){while(h--)p={p.second,-p.first};return p;}P add(P a,P b){return{a.first+b.first,a.second+b.second};}P sub(P a,P b){return{a.first-b.first,a.second-b.second};}
int dx[]={0,1,0,-1},dy[]={1,0,-1,0};struct G{string name,w;P end;int dh;map<P,int>req;set<P>odd;};vector<G>M;map<P,int>B;vector<int>path;mt19937 rng;long long nodes,cap;int depth;bool stopped,hit;P q;struct Goal{int b,h;P p;};vector<Goal>goals; vector<set<tuple<int,int,int>>> reach;
set<array<int,5>>F;set<array<int,7>>FP;int sourceid;
bool forbidden(int a,int b,P p,int h,P q){return F.count({a,b,p.first,p.second,h})||FP.count({a,b,p.first,p.second,h,q.first,q.second});}
struct Undo{vector<pair<P,int>>x;};bool apply(int a,P p,int h,Undo&u){auto&g=M[a];for(auto[z,c]:g.req){P v=add(p,rot(z,h));auto it=B.find(v);if(it!=B.end()){if(it->second!=c)return false;}else{u.x.push_back({v,-1});B[v]=c;}}for(P z:g.odd){P v=add(p,rot(z,h));u.x.push_back({v,B[v]});B[v]^=1;}return true;}void undo(Undo&u){for(auto it=u.x.rbegin();it!=u.x.rend();++it)if(it->second<0)B.erase(it->first);else B[it->first]=it->second;}
void dfs(P p,int h,int left,uint64_t valid){if(++nodes>cap){stopped=true;return;}for(int gi=0;gi<(int)goals.size();gi++)if(valid&(1ull<<gi))if(auto goal=goals[gi];goal.p==p&&goal.h==h){Undo u;if(apply(goal.b,p,h,u)){P ep=add(p,rot(M[goal.b].end,h));int eh=(h+M[goal.b].dh)%4;for(int k:{0,1,4,5,6,7,8,9}){Undo v;if(apply(k,ep,eh,v)){cout<<"HIT";for(int a:path)cout<<' '<<M[a].name;cout<<' '<<M[goal.b].name<<' '<<M[k].name<<" | q "<<q.first<<' '<<q.second<<endl;hit=stopped=true;}undo(v);if(hit)break;}}undo(u);if(hit)return;}if(left==0)return; bool can=false; for(int gi=0;gi<(int)goals.size();gi++){if(!(valid&(1ull<<gi)))continue;auto g=goals[gi];P d=rot(sub(g.p,p),(4-h)%4); if(reach[left].count({d.first,d.second,(g.h-h+4)%4})){can=true;break;}} if(!can)return; array<int,8>order={0,1,4,5,6,7,8,9};shuffle(order.begin(),order.end(),rng);for(int a:order){P lq=rot(sub(q,p),(4-h)%4);if(M[a].req.count(lq)||forbidden(sourceid,a,p,h,q))continue;uint64_t nv=0;for(int gi=0;gi<(int)goals.size();gi++){auto g=goals[gi];if((valid&(1ull<<gi))&&!forbidden(a,g.b,rot(sub(g.p,p),(4-h)%4),(g.h-h+4)%4,lq))nv|=1ull<<gi;}if(!nv)continue;Undo u;if(apply(a,p,h,u)){path.push_back(a);dfs(add(p,rot(M[a].end,h)),(h+M[a].dh)%4,left-1,nv);path.pop_back();}undo(u);if(stopped)return;}}
int main(int argc,char**argv){for(int arg=5;arg<argc;arg++){ifstream in(argv[arg]);string line;while(getline(in,line)){istringstream ss(line);if(arg==5){array<int,5>v;for(int&x:v)ss>>x;F.insert(v);}else{array<int,7>v;for(int&x:v)ss>>x;FP.insert(v);}}}ifstream f(argv[1]);int n;f>>n;M.resize(n);string mark="LLLLRLRRRRL";for(auto&g:M){f>>g.name>>g.w;P p={0,0};int h=0;map<P,int>last;string text=g.w+mark;for(int i=0;i<(int)text.size();i++){int c=text[i]=='L';if(last.count(p))assert(last[p]!=c);last[p]=c;g.req.emplace(p,c);if(i<(int)g.w.size()){if(g.odd.count(p))g.odd.erase(p);else g.odd.insert(p);}h=(h+(c?3:1))%4;p={p.first+dx[h],p.second+dy[h]};if(i+1==(int)g.w.size()){g.end=p;g.dh=h;}}}int groups;f>>groups;cap=stoll(argv[2]);depth=stoi(argv[3]);rng.seed(stoi(argv[4])); reach.resize(depth+1); reach[0].insert({0,0,0}); for(int t=1;t<=depth;t++){reach[t]=reach[t-1]; for(auto[x,y,h]:reach[t-1])for(int a:{0,1,4,5,6,7,8,9}){P p=add({x,y},rot(M[a].end,h));reach[t].insert({p.first,p.second,(h+M[a].dh)%4});}} for(int gi=0;gi<groups;gi++){int a,z;f>>a>>q.first>>q.second>>z;goals.clear();while(z--){Goal g;f>>g.b>>g.p.first>>g.p.second>>g.h;goals.push_back(g);}sourceid=a;B.clear();path={a};Undo u;assert(apply(a,{0,0},0,u));nodes=0;stopped=hit=false;dfs(M[a].end,M[a].dh,depth,(1ull<<goals.size())-1);cout<<"GROUP "<<gi<<" source "<<M[a].name<<" q "<<q.first<<' '<<q.second<<" nodes "<<nodes<<" cap "<<(stopped&&!hit)<<" hit "<<hit<<endl;if(hit)return 0;}}
